CREATE TABLE refuse_ship_pins(what TEXT NOT NULL, n INTEGER NOT NULL CHECK (n = 0)) STRICT;
INSERT INTO refuse_ship_pins SELECT 'a row with a document, no fill, or a field left in rest', count(*) FROM ship_pins WHERE body <> '{}' OR rest IS NULL OR json_type(rest, '$.repos') IS NOT NULL OR json_type(rest, '$.ruff') IS NOT NULL OR json_type(rest, '$.sweep') IS NOT NULL OR json_type(rest, '$.tag') IS NOT NULL;
DROP TABLE refuse_ship_pins;
DROP TRIGGER ship_pins_fill;
DROP TRIGGER ship_pins_refill;
DROP TRIGGER ship_pins_bad;
ALTER TABLE ship_pins DROP COLUMN body;
CREATE TRIGGER ship_pins_rest_insert BEFORE INSERT ON ship_pins WHEN json_type(NEW.rest, '$.repos') IS NOT NULL OR json_type(NEW.rest, '$.ruff') IS NOT NULL OR json_type(NEW.rest, '$.sweep') IS NOT NULL OR json_type(NEW.rest, '$.tag') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'ship_pins.rest holds a field that has a column'); END;
