 '$.install') IS NOT NULL OR json_type(rest, '$.item') IS NOT NULL OR json_type(rest, '$.land_wait_s') IS NOT NULL OR json_type(rest, '$.load1') IS NOT NULL OR json_type(rest, '$.loopctl') IS NOT NULL OR json_type(rest, '$.name') IS NOT NULL OR json_type(rest, '$.own_s') IS NOT NULL OR json_type(rest, '$.pid') IS NOT NULL OR json_type(rest, '$.pid_stamp') IS NOT NULL OR json_type(rest, '$.preflight') IS NOT NULL OR json_type(rest, '$.progress') IS NOT NULL OR json_type(rest, '$.quiet.idle_pct') IS NOT NULL OR json_type(rest, '$.quiet.idle_pct_first') IS NOT NULL OR json_type(rest, '$.quiet.load1') IS NOT NULL OR json_type(rest, '$.quiet.max_s') IS NOT NULL OR json_type(rest, '$.quiet.min_idle_pct') IS NOT NULL OR json_type(rest, '$.quiet.off') IS NOT NULL OR json_type(rest, '$.quiet.quiet') IS NOT NULL OR json_type(rest, '$.quiet.readings') IS NOT NULL OR json_type(rest, '$.quiet.unmeasured') IS NOT NULL OR json_type(rest, '$.quiet.waited_s') IS NOT NULL OR json_type(rest, '$.quiet_settings') IS NOT NULL OR json_type(rest, '$.release') IS NOT NULL OR json_type(rest, '$.release_pushes') IS NOT NULL OR json_type(rest, '$.remote') IS NOT NULL OR json_type(rest, '$.repo') IS NOT NULL OR json_type(rest, '$.result') IS NOT NULL OR json_type(rest, '$.retried') IS NOT NULL OR json_type(rest, '$.sha') IS NOT NULL OR json_type(rest, '$.started') IS NOT NULL OR json_type(rest, '$.status') IS NOT NULL OR json_type(rest, '$.steps') IS NOT NULL OR json_type(rest, '$.summary') IS NOT NULL OR json_type(rest, '$.tail') IS NOT NULL OR json_type(rest, '$.timeout_s') IS NOT NULL OR json_type(rest, '$.undo') IS NOT NULL OR json_type(rest, '$.verdicts') IS NOT NULL OR json_type(rest, '$.version') IS NOT NULL;
